/* ── 변수 ── */
:root {
  --hwp-primary: #1a73e8;
  --hwp-primary-hover: #1557b0;
  --hwp-toolbar-bg: #38a9ff;
  --hwp-toolbar-edge: var(--hwp-primary);
  --hwp-toolbar-border: var(--background-modifier-border);
  --hwp-toolbar-btn-border: #004d99;
  --hwp-toolbar-btn-hover: var(--background-modifier-hover);
  --hwp-toolbar-btn-active: var(--interactive-accent);
  --hwp-toolbar-btn-text: var(--text-normal);
  --hwp-toolbar-logo-size: clamp(24px, 3vw, 40px);
  --hwp-toolbar-logo-gap: clamp(4px, 0.6vw, 10px);
  --hwp-toolbar-logo-right: clamp(8px, 1.2vw, 16px);
  --hwp-toolbar-logo-top: clamp(3px, 0.5vw, 7px);
  --hwp-paper-bg: #ffffff;
  --hwp-paper-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
  --hwp-paper-border: #d0d0d0;
}

/* ── HanMark 2.x: bundled Kordoc export center and quick HWPX preview ── */
.hanmark-export-modal {
  --hanmark-export-key-color: var(--interactive-accent);
  --hanmark-export-key-text: var(--text-on-accent);
  --hanmark-export-logo-body: #1565c0;
  --hanmark-export-logo-accent: #42adff;
  --hanmark-export-logo-muted: #283593;
  --hanmark-export-logo-text: #fff;
  container-type: inline-size;
  display: flex;
  flex-direction: column;
  gap: 16px;
  width: 100%;
  max-width: none;
}

.hanmark-export-modal.hwp-toolbar-skin-light,
.hanmark-export-modal.hwp-toolbar-skin-auto {
  --hanmark-export-key-color: var(--hwp-toolbar-light-btn-border, var(--interactive-accent));
  --hanmark-export-logo-body: var(--hwp-toolbar-light-logo-body, #1565c0);
  --hanmark-export-logo-accent: var(--hwp-toolbar-light-logo-accent, #42adff);
  --hanmark-export-logo-muted: var(--hwp-toolbar-light-logo-muted, #283593);
  --hanmark-export-logo-text: var(--hwp-toolbar-light-logo-text, #fff);
}

.hanmark-export-modal.hwp-toolbar-skin-dark,
.theme-dark .hanmark-export-modal.hwp-toolbar-skin-auto {
  --hanmark-export-key-color: var(--hwp-toolbar-dark-btn-border, var(--interactive-accent));
  --hanmark-export-logo-body: var(--hwp-toolbar-dark-logo-body, #94d600);
  --hanmark-export-logo-accent: var(--hwp-toolbar-dark-logo-accent, #b6ff00);
  --hanmark-export-logo-muted: var(--hwp-toolbar-dark-logo-muted, #5f7a0a);
  --hanmark-export-logo-text: var(--hwp-toolbar-dark-logo-text, #121212);
}

.hanmark-export-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
}

.hanmark-export-header h2,
.hanmark-export-header p {
  margin: 0;
}

.hanmark-export-header p {
  margin-top: 4px;
  color: var(--text-muted);
}

.hanmark-export-header .hanmark-window-size-hint {
  flex: 0 0 auto;
  margin: 5px 0 0;
  text-align: right;
}

.hanmark-export-format-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.hanmark-export-format-card {
  display: grid;
  grid-template-columns: 64px minmax(0, 1fr);
  gap: 16px;
  align-items: center;
  min-height: 132px;
  margin: 0;
  padding: 18px;
  border: 2px solid var(--background-modifier-border);
  border-radius: 16px;
  background: var(--background-secondary);
  color: var(--text-normal);
  text-align: left;
  white-space: normal;
  cursor: pointer;
  transition:
    border-color 120ms ease,
    background-color 120ms ease,
    box-shadow 120ms ease,
    transform 120ms ease;
}

.hanmark-export-format-card:hover {
  border-color: color-mix(
    in srgb,
    var(--hanmark-export-key-color) 60%,
    var(--background-modifier-border)
  );
  background: var(--background-modifier-hover);
  transform: translateY(-1px);
}

.hanmark-export-format-card:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--hanmark-export-key-color) 58%, transparent);
  outline-offset: 2px;
}

.hanmark-export-format-card.is-selected {
  border-color: var(--hanmark-export-key-color);
  background: color-mix(
    in srgb,
    var(--hanmark-export-key-color) 12%,
    var(--background-secondary)
  );
  box-shadow: 0 0 0 1px var(--hanmark-export-key-color);
}

.hanmark-export-format-icon {
  display: grid;
  place-items: center;
  width: 56px;
  height: 56px;
  color: var(--hanmark-export-key-color);
  background-position: center;
  background-repeat: no-repeat;
  background-size: contain;
}

.hanmark-export-format-icon svg {
  display: block;
  width: 100%;
  height: 100%;
}

.hanmark-export-modal.hwp-toolbar-skin-light .hanmark-export-format-icon.is-hwpx,
.hanmark-export-modal.hwp-toolbar-skin-auto .hanmark-export-format-icon.is-hwpx {
  background-image: var(--hwp-toolbar-light-logo-hwp);
}

.hanmark-export-modal.hwp-toolbar-skin-light .hanmark-export-format-icon.is-docx,
.hanmark-export-modal.hwp-toolbar-skin-auto .hanmark-export-format-icon.is-docx {
  background-image: var(--hwp-toolbar-light-logo-word);
}

.hanmark-export-modal.hwp-toolbar-skin-dark .hanmark-export-format-icon.is-hwpx,
.theme-dark .hanmark-export-modal.hwp-toolbar-skin-auto .hanmark-export-format-icon.is-hwpx {
  background-image: var(--hwp-toolbar-dark-logo-hwp);
}

.hanmark-export-modal.hwp-toolbar-skin-dark .hanmark-export-format-icon.is-docx,
.theme-dark .hanmark-export-modal.hwp-toolbar-skin-auto .hanmark-export-format-icon.is-docx {
  background-image: var(--hwp-toolbar-dark-logo-word);
}

.hanmark-export-modal.hwp-toolbar-skin-light .hanmark-export-format-icon:is(.is-hwpx, .is-docx) svg,
.hanmark-export-modal.hwp-toolbar-skin-dark .hanmark-export-format-icon:is(.is-hwpx, .is-docx) svg,
.hanmark-export-modal.hwp-toolbar-skin-auto .hanmark-export-format-icon:is(.is-hwpx, .is-docx) svg {
  visibility: hidden;
}

.hanmark-export-format-copy {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.hanmark-export-format-copy strong {
  font-size: 1.25rem;
  line-height: 1.2;
}

.hanmark-export-format-copy small {
  color: var(--text-muted);
  font-size: var(--font-ui-small);
  line-height: 1.45;
}

.hanmark-export-detail {
  padding: 18px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 16px;
  background: var(--background-primary-alt);
}

.hanmark-export-detail h3,
.hanmark-export-detail > p {
  margin-top: 0;
}

.hanmark-export-detail > p:last-child {
  margin-bottom: 0;
}

.hanmark-compact-engine-line {
  margin: 6px 0 12px;
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
}

.hanmark-export-template-row {
  display: grid;
  grid-template-columns: minmax(120px, auto) minmax(0, 1fr);
  gap: 8px;
  align-items: center;
}

.hanmark-export-template-row select {
  min-width: 0;
  width: 100%;
}

.hanmark-export-template-row small {
  grid-column: 2;
  color: var(--text-muted);
}

.hanmark-export-field-label {
  color: var(--text-muted);
  font-size: var(--font-ui-small);
  font-weight: var(--font-semibold);
}

.hanmark-export-variant-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin-top: 16px;
}

.hanmark-export-variant {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-height: 88px;
  padding: 12px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 12px;
  background: var(--background-secondary);
  color: var(--text-normal);
  text-align: left;
  white-space: normal;
  cursor: pointer;
  transition:
    border-color 120ms ease,
    background-color 120ms ease,
    box-shadow 120ms ease;
}

.hanmark-export-variant:hover {
  border-color: color-mix(
    in srgb,
    var(--hanmark-export-key-color) 55%,
    var(--background-modifier-border)
  );
  background: var(--background-modifier-hover);
}

.hanmark-export-variant:focus-visible,
.hanmark-export-preview-row .hanmark-export-secondary-action:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--hanmark-export-key-color) 58%, transparent);
  outline-offset: 2px;
}

.hanmark-export-variant.is-selected {
  border-color: var(--hanmark-export-key-color);
  background: color-mix(
    in srgb,
    var(--hanmark-export-key-color) 10%,
    var(--background-secondary)
  );
}

.hanmark-export-variant small {
  color: var(--text-muted);
  line-height: 1.35;
}

.hanmark-export-preview-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 14px;
  padding: 12px 0 0;
  border-top: 1px solid var(--background-modifier-border);
}

.hanmark-export-preview-copy {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.hanmark-export-preview-copy small {
  color: var(--text-muted);
  line-height: 1.4;
}

.hanmark-export-preview-row .hanmark-export-secondary-action {
  flex: 0 0 auto;
  margin-top: 0;
}

.hanmark-export-option-row {
  display: grid;
  grid-template-columns: minmax(120px, auto) minmax(0, 1fr);
  gap: 8px;
  align-items: center;
  margin-top: 12px;
}

.hanmark-export-option-row select {
  min-width: 0;
  width: 100%;
}

.hanmark-export-secondary-action {
  margin-top: 12px;
}

.hanmark-export-summary-card {
  display: grid;
  grid-template-columns: minmax(150px, auto) minmax(0, 1fr);
  gap: 5px 12px;
  align-items: baseline;
  padding: 14px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 12px;
  background: var(--background-secondary);
}

.hanmark-export-summary-card > span {
  color: var(--text-muted);
  font-size: var(--font-ui-small);
}

.hanmark-export-summary-card small {
  grid-column: 1 / -1;
  color: var(--text-muted);
  line-height: 1.45;
}

.hanmark-export-secondary-actions,
.hanmark-export-result-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 12px;
}

.hanmark-export-native-note {
  display: block;
  padding: 10px 12px;
  border-left: 3px solid var(--hanmark-export-key-color);
  background: var(--background-secondary);
  color: var(--text-muted);
}

.hanmark-export-result {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 14px 16px;
  border: 1px solid color-mix(
    in srgb,
    var(--color-green) 55%,
    var(--background-modifier-border)
  );
  border-radius: 14px;
  background: color-mix(
    in srgb,
    var(--color-green) 9%,
    var(--background-secondary)
  );
}

.hanmark-export-result code {
  overflow-wrap: anywhere;
  user-select: text;
}

.hanmark-export-result ul {
  margin: 0;
  padding-left: 20px;
  color: var(--text-muted);
}

.hanmark-export-footer {
  position: sticky;
  bottom: -16px;
  z-index: 3;
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: auto;
  padding: 12px 0 2px;
  border-top: 1px solid var(--background-modifier-border);
  background: var(--background-primary);
}

.hanmark-export-primary-button {
  flex: 1;
  min-height: 42px;
  font-weight: var(--font-semibold);
}

.hanmark-export-footer .hanmark-modal-close {
  min-height: 42px;
  margin-top: 0;
}

@container (max-width: 700px) {
  .hanmark-export-format-grid {
    grid-template-columns: 1fr;
  }

  .hanmark-export-format-card {
    min-height: 104px;
  }

  .hanmark-export-variant-grid {
    grid-template-columns: 1fr;
  }

  .hanmark-export-preview-row {
    align-items: stretch;
    flex-direction: column;
    gap: 10px;
  }

  .hanmark-export-preview-row .hanmark-export-secondary-action {
    width: 100%;
  }

  .hanmark-export-header {
    flex-direction: column;
    gap: 6px;
  }

  .hanmark-export-header .hanmark-window-size-hint {
    text-align: left;
  }

  .hanmark-export-template-row,
  .hanmark-export-option-row,
  .hanmark-export-summary-card {
    grid-template-columns: 1fr;
  }

  .hanmark-export-template-row small,
  .hanmark-export-summary-card small {
    grid-column: 1;
  }
}

.hanmark-engine-status {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 10px 0 18px;
  padding: 13px 15px;
  border: 1px solid color-mix(in srgb, var(--color-green) 42%, var(--background-modifier-border));
  border-radius: 10px;
  background: color-mix(in srgb, var(--color-green) 8%, var(--background-secondary));
}

.hanmark-engine-status strong {
  color: var(--color-green);
}

.hanmark-engine-status span {
  color: var(--text-muted);
  font-size: var(--font-ui-small);
}

.hanmark-export-card {
  margin: 10px 0;
  padding: 14px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 10px;
  background: var(--background-secondary);
}

.hanmark-export-card h4,
.hanmark-export-card p {
  margin-top: 0;
}

.hanmark-export-card p {
  color: var(--text-muted);
}

.hanmark-export-utilities,
.hanmark-advanced-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 12px 0 18px;
}

.hanmark-table-style,
.hanmark-document-style {
  margin: 14px 0;
  padding: 12px 14px;
  border-left: 3px solid var(--interactive-accent);
  background: var(--background-secondary-alt);
}

.hanmark-table-style h3,
.hanmark-table-style p,
.hanmark-document-style h3,
.hanmark-document-style p {
  margin-top: 0;
}

.hanmark-settings-document-style,
.hanmark-settings-table-style {
  margin-bottom: 18px;
}

.hanmark-document-style-modal {
  max-width: 780px;
}

.hanmark-document-style-role,
.hanmark-document-style-page {
  margin: 14px 0;
  padding: 8px 14px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 10px;
  background: var(--background-secondary);
}

.hanmark-document-style-role {
  padding: 0;
  overflow: hidden;
}

.hanmark-document-style-role.is-open {
  padding: 0 14px 8px;
  border-color: color-mix(in srgb, var(--interactive-accent) 55%, var(--background-modifier-border));
}

.hanmark-document-style-role-toggle {
  display: flex;
  justify-content: space-between;
  width: calc(100% + 28px);
  margin: 0 -14px;
  padding: 11px 14px;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--text-normal);
  font-weight: var(--font-semibold);
  text-align: left;
}

.hanmark-document-style-role:not(.is-open) .hanmark-document-style-role-toggle {
  width: 100%;
  margin: 0;
}

.hanmark-document-style-role-toggle:hover {
  background: var(--background-modifier-hover);
}

.hanmark-document-style-role-chevron {
  color: var(--text-muted);
}

.hanmark-template-manager {
  width: min(760px, calc(100vw - 48px));
  max-width: 760px;
  max-height: 78vh;
  overflow-y: auto;
  padding-right: 6px;
}

.hanmark-template-group {
  margin-top: 14px;
}

.hanmark-template-group h3 {
  margin: 0 0 6px;
  color: var(--text-muted);
  font-size: var(--font-ui-small);
}

.hanmark-template-row {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 10px 12px;
  border: 1px solid var(--background-modifier-border);
  border-bottom-width: 0;
  cursor: pointer;
}

.hanmark-template-row:first-of-type {
  border-radius: 10px 10px 0 0;
}

.hanmark-template-row:last-child {
  border-bottom-width: 1px;
  border-radius: 0 0 10px 10px;
}

.hanmark-template-row:only-of-type {
  border-radius: 10px;
}

.hanmark-template-row.is-selected {
  border-color: var(--interactive-accent);
  background: color-mix(in srgb, var(--interactive-accent) 10%, var(--background-secondary));
}

.hanmark-template-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.hanmark-template-info small {
  overflow: hidden;
  color: var(--text-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.hanmark-template-active {
  padding: 3px 8px;
  border-radius: 999px;
  background: var(--interactive-accent);
  color: var(--text-on-accent);
  font-size: var(--font-ui-smaller);
}

.hanmark-template-actions,
.hanmark-template-add,
.hanmark-dialog-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 14px;
}

.hanmark-template-add {
  padding-top: 14px;
  border-top: 1px solid var(--background-modifier-border);
}

.hanmark-docx-settings {
  margin: 12px 0 18px;
  padding: 10px 12px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 10px;
  background: var(--background-secondary);
}

.hanmark-docx-settings > summary {
  cursor: pointer;
  font-weight: var(--font-semibold);
}

@media (max-width: 600px) {
  .hanmark-template-manager {
    width: calc(100vw - 24px);
  }

  .hanmark-export-format-grid,
  .hanmark-export-variant-grid {
    grid-template-columns: 1fr;
  }

  .hanmark-export-format-card {
    min-height: 104px;
  }

  .hanmark-export-footer {
    align-items: stretch;
    flex-direction: column;
  }
}

.hanmark-document-style-role h3,
.hanmark-document-style-page h3 {
  margin-bottom: 4px;
}

.hanmark-advanced-note {
  color: var(--text-muted);
  font-size: var(--font-ui-small);
}

.hanmark-modal-close {
  margin-top: 12px;
}

.hanmark-advanced-settings {
  margin: 18px 0;
  padding: 12px 14px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 10px;
  background: var(--background-secondary);
}

.hanmark-advanced-settings > summary {
  cursor: pointer;
  font-weight: var(--font-semibold);
}

.hanmark-quick-preview {
  height: 100%;
  overflow: auto;
  background: var(--background-secondary);
}

.hanmark-preview-caution {
  position: sticky;
  top: 0;
  z-index: 2;
  padding: 9px 12px;
  border-bottom: 1px solid var(--background-modifier-border);
  background: color-mix(in srgb, var(--color-yellow) 13%, var(--background-primary));
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
}

.hanmark-preview-stage {
  padding: 14px;
}

.hanmark-preview-loading,
.hanmark-preview-error {
  padding: 18px;
  border-radius: 8px;
  background: var(--background-primary);
}

.hanmark-preview-error {
  color: var(--text-error);
}

.hanmark-preview-summary {
  margin-bottom: 8px;
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
}

.hanmark-preview-warnings {
  margin-bottom: 10px;
  padding: 8px 10px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 8px;
  background: var(--background-primary);
  font-size: var(--font-ui-smaller);
}

.hanmark-preview-paper {
  margin: 0 auto;
  max-width: 900px;
  overflow: hidden;
  border-radius: 4px;
  box-shadow: 0 8px 28px rgb(0 0 0 / 18%);
  background: white;
}

.hanmark-preview-paper svg {
  display: block;
}


.theme-dark {
  --hwp-paper-bg: #f8f8f8;
  --hwp-paper-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
  --hwp-paper-border: #555;
}

/* ================================================================
   HWP TOOLBAR — 마크다운 에디터 내부에 삽입되는 DOM 툴바
   ================================================================ */

.hwp-toolbar-container.hwp-toolbar-skin-auto,
.hwp-toolbar-container.hwp-toolbar-skin-light {
  --hwp-toolbar-bg: var(--hwp-toolbar-light-bg);
  --hwp-toolbar-edge: var(--hwp-toolbar-light-edge);
  --hwp-toolbar-btn-border: var(--hwp-toolbar-light-btn-border);
  --hwp-toolbar-logo-hwp: var(--hwp-toolbar-light-logo-hwp);
  --hwp-toolbar-logo-word: var(--hwp-toolbar-light-logo-word);
}

.theme-dark .hwp-toolbar-container.hwp-toolbar-skin-auto,
.hwp-toolbar-container.hwp-toolbar-skin-dark {
  --hwp-toolbar-bg: var(--hwp-toolbar-dark-bg);
  --hwp-toolbar-edge: var(--hwp-toolbar-dark-edge);
  --hwp-toolbar-btn-border: var(--hwp-toolbar-dark-btn-border);
  --hwp-toolbar-logo-hwp: var(--hwp-toolbar-dark-logo-hwp);
  --hwp-toolbar-logo-word: var(--hwp-toolbar-dark-logo-word);
}

.hwp-toolbar-container {
  position: sticky;
  top: 0;
  z-index: 10;
  background: var(--hwp-toolbar-bg);
  border-bottom: 2px solid var(--hwp-toolbar-edge);
  padding: 2px 6px;
  padding-right: calc(
    (var(--hwp-toolbar-logo-size) * 2) +
    var(--hwp-toolbar-logo-gap) +
    var(--hwp-toolbar-logo-right) +
    12px
  );
  flex-shrink: 0;
  user-select: none;
  min-height: unset;
}

.hwp-toolbar-container::before,
.hwp-toolbar-container::after {
  content: "";
  position: absolute;
  top: var(--hwp-toolbar-logo-top);
  width: var(--hwp-toolbar-logo-size);
  height: var(--hwp-toolbar-logo-size);
  background-position: center;
  background-size: contain;
  background-repeat: no-repeat;
  pointer-events: none;
  z-index: 1;
}

.hwp-toolbar-container::before {
  right: calc(
    var(--hwp-toolbar-logo-right) +
    var(--hwp-toolbar-logo-size) +
    var(--hwp-toolbar-logo-gap)
  );
  background-image: var(--hwp-toolbar-logo-hwp, url("data:image/svg+xml;base64,"));
}

.hwp-toolbar-container::after {
  right: var(--hwp-toolbar-logo-right);
  background-image: var(--hwp-toolbar-logo-word, url("data:image/svg+xml;base64,"));
}

.hwp-toolbar-main,
.hwp-toolbar-format {
  display: flex;
  align-items: center;
  gap: 2px;
  flex-wrap: wrap;
  min-height: 32px;
  padding: 2px 0;
}

.hwp-toolbar-group {
  display: flex;
  align-items: center;
  gap: 1px;
  flex-shrink: 0;
}

.hwp-toolbar-export-group {
  flex: 0 1 auto;
  flex-wrap: wrap;
  min-width: 0;
  max-width: 100%;
}

.hwp-toolbar-divider {
  width: 1px;
  height: 20px;
  background: var(--hwp-toolbar-border);
  margin: 0 4px;
  flex-shrink: 0;
}

/* 툴바 버튼 */
.hwp-toolbar-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 28px;
  height: 26px;
  padding: 2px 6px;
  border: 2px solid var(--hwp-toolbar-btn-border);
  border-radius: 4px;
  background: transparent;
  color: var(--hwp-toolbar-btn-text);
  cursor: pointer;
  font-size: 12px;
  transition: background 0.1s;
}

.hwp-toolbar-btn:hover {
  background: var(--hwp-toolbar-btn-hover);
}

.hwp-toolbar-btn:active {
  background: var(--hwp-toolbar-btn-active);
  color: white;
}

.hwp-toolbar-btn.is-active {
  background: var(--hwp-primary);
  color: white;
}

.hwp-toolbar-btn svg {
  width: 16px;
  height: 16px;
}

.hwp-toolbar-btn-label {
  font-weight: 600;
  font-size: 11px;
  letter-spacing: -0.3px;
}

/* 드롭다운 메뉴 */
.hwp-toolbar-menu {
  position: relative;
}

.hwp-toolbar-menu-panel {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  z-index: 30;
  min-width: 170px;
  max-width: 280px;
  max-height: 300px;
  overflow-y: auto;
  display: none;
  flex-direction: column;
  gap: 2px;
  padding: 6px;
  border: 2px solid var(--hwp-toolbar-btn-border);
  border-radius: 6px;
  background: var(--background-primary);
  box-shadow: 0 8px 18px rgba(0, 0, 0, 0.2);
}

.hwp-toolbar-menu.is-open .hwp-toolbar-menu-panel {
  display: flex;
}

.hwp-toolbar-menu-item {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  min-height: 28px;
  padding: 4px 8px;
  border: 1px solid var(--hwp-toolbar-border);
  border-radius: 4px;
  background: transparent;
  color: var(--text-normal);
  cursor: pointer;
  text-align: left;
  font-size: 12px;
}

.hwp-toolbar-menu-item:hover {
  background: var(--hwp-toolbar-btn-hover);
}

.hwp-toolbar-menu-item:active {
  background: var(--hwp-toolbar-btn-active);
  color: white;
}

.hwp-toolbar-menu-divider {
  height: 1px;
  background: var(--hwp-toolbar-border);
  margin: 4px 0;
}

/* 스타일 드롭다운 */
.hwp-style-dropdown {
  height: 26px;
  padding: 2px 8px;
  border: 2px solid var(--hwp-toolbar-btn-border);
  border-radius: 4px;
  background: var(--background-primary);
  color: var(--text-normal);
  font-size: 12px;
  cursor: pointer;
  min-width: 120px;
}

.hwp-style-dropdown:focus {
  border-color: var(--hwp-toolbar-btn-border);
  outline: none;
}

/* ================================================================
   PREVIEW — A4 용지 뷰
   ================================================================ */

.hwp-preview-container {
  background: var(--background-secondary);
  padding: 24px;
  overflow: auto;
  display: flex;
  justify-content: center;
}

.hwp-paper-frame {
  width: max-content;
  max-width: 100%;
}

.hwp-paper {
  background: var(--hwp-paper-bg);
  box-shadow: var(--hwp-paper-shadow);
  border: 1px solid var(--hwp-paper-border);
  width: var(--hwp-paper-width, 595.3pt);
  min-height: var(--hwp-paper-height, 841.9pt);
  padding: var(--hwp-paper-padding, 42.6pt 72pt 49.6pt 72pt);
  box-sizing: border-box;
  /* Obsidian 전역 폰트 변수 무시 — HWP 템플릿 폰트가 최우선 */
  --font-text: unset;
  --font-text-override: unset;
  --font-interface: unset;
  --default-font: unset;
  font-family: serif;
  font-size: 10pt;
  line-height: 1.6;
  color: #1a1a1a;
  word-break: keep-all;
  overflow-wrap: break-word;
  display: flex;
  flex-direction: column;
}

/* ── 미리보기 종이의 테마 색 격리 ──
   문서 미리보기는 종이처럼 고정색이어야 하는데, Obsidian 테마가 strong/b/h1~h6와 여러 색
   변수를 통해 액센트(키) 컬러를 새어보낸다. 두 겹으로 차단한다.
   1) 테마 변수 pin — var() 기반 테마 규칙을 specificity 무관하게 무력화(currentColor로 해소).
   2) 요소 색 리셋 — 정확히 (0,1,1) specificity 유지. 프리뷰 컨테이너가 주입하는 인라인
      <style>이 문서 순서로 이기므로, 템플릿에서 추출된 비검정 제목색은 그대로 살아남는다.
      강제 우선순위나 이중-클래스 셀렉터는 쓰지 않는다(추출된 색을 덮어버린다). */
.hwp-paper,
.word-template-preview-paper {
  --h1-color: currentColor;
  --h2-color: currentColor;
  --h3-color: currentColor;
  --h4-color: currentColor;
  --h5-color: currentColor;
  --h6-color: currentColor;
  --bold-color: currentColor;
  --italic-color: currentColor;
  --bold-weight: bold;
  --code-normal: currentColor;
}
.hwp-paper {
  --text-normal: #1a1a1a;
}
.word-template-preview-paper {
  --text-normal: #111;
}
.hwp-paper :is(h1, h2, h3, h4, h5, h6, strong, b, em, mark, code),
.word-template-preview-paper :is(h1, h2, h3, h4, h5, h6, strong, b, em, mark, code) {
  color: inherit;
}
.hwp-paper :is(strong, b),
.word-template-preview-paper :is(strong, b) {
  font-weight: bold;
}

/* HWP 레벨별 스타일 */
.hwp-line {
  margin: 0;
  padding: 0;
  /* 인라인 스타일의 font-family가 최우선 되도록 */
  font-family: inherit;
}

.hwp-line.hwp-empty {
  height: 1.2em;
}

.hwp-line.hwp-title {
  margin-top: 16px;
  margin-bottom: 8px;
}

.hwp-line.hwp-subtitle {
  margin-top: 12px;
  margin-bottom: 6px;
}

.hwp-line.hwp-note {
  color: #555;
}

.hwp-preview-empty {
  text-align: center;
  color: var(--text-muted);
  padding: 60px 20px;
  font-size: 14px;
}

/* ================================================================
   SETUP GUIDE MODAL (설치 가이드)
   ================================================================ */

.hwp-setup-guide {
  max-width: 640px;
  padding: 0 8px;
}

.hwp-setup-guide h1 {
  text-align: center;
  margin-bottom: 4px;
}

.hwp-setup-subtitle {
  text-align: center;
  color: var(--text-muted);
  font-size: 14px;
  margin-bottom: 20px;
}

.hwp-setup-step {
  margin-bottom: 24px;
  padding: 16px;
  background: var(--background-secondary);
  border-radius: 8px;
  border-left: 4px solid var(--hwp-primary);
}

.hwp-setup-step h2 {
  margin-top: 0;
  font-size: 16px;
}

.hwp-setup-step p {
  color: var(--text-muted);
  font-size: 13px;
  margin-bottom: 12px;
}

.hwp-setup-howto h3 {
  font-size: 13px;
  margin: 12px 0 6px;
  color: var(--text-normal);
}

.hwp-setup-howto ol {
  padding-left: 20px;
  font-size: 13px;
  line-height: 1.8;
}

.hwp-setup-howto ol li {
  margin-bottom: 4px;
}

.hwp-setup-howto a {
  color: var(--hwp-primary);
  text-decoration: underline;
}

.hwp-setup-warning {
  background: #fff3cd;
  border: 1px solid #ffc107;
  border-radius: 6px;
  padding: 8px 12px;
  font-size: 12px;
  margin-top: 8px;
  color: #856404;
}

.theme-dark .hwp-setup-warning {
  background: #3d3200;
  border-color: #665200;
  color: #ffd700;
}

.hwp-setup-cmd {
  background: var(--background-primary);
  border: 1px solid var(--hwp-toolbar-border);
  border-radius: 6px;
  padding: 10px 14px;
  margin: 8px 0;
  font-family: monospace;
}

.hwp-setup-cmd code {
  font-size: 13px;
  word-break: break-all;
}

.hwp-setup-copy-btn {
  display: inline-block;
  margin-top: 6px;
  padding: 4px 12px;
  font-size: 12px;
  border: 1px solid var(--hwp-toolbar-border);
  border-radius: 4px;
  background: var(--background-secondary);
  color: var(--text-normal);
  cursor: pointer;
}

.hwp-setup-copy-btn:hover {
  background: var(--background-modifier-hover);
}

/* 설치 상태 테이블 */
.hwp-setup-status {
  margin-bottom: 16px;
}

.hwp-setup-status h3 {
  font-size: 14px;
  margin-bottom: 8px;
}

.hwp-setup-status-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.hwp-setup-status-table td {
  padding: 6px 10px;
  border-bottom: 1px solid var(--hwp-toolbar-border);
}

.hwp-setup-status-table td:first-child {
  font-weight: 600;
  width: 140px;
}

.hwp-status-ok {
  color: #28a745;
}

.hwp-status-fail {
  color: #dc3545;
}

.hwp-status-all-good {
  background: #d4edda;
  border-radius: 6px;
  padding: 10px 14px;
  margin-top: 12px;
  font-size: 13px;
  color: #155724;
}

.theme-dark .hwp-status-all-good {
  background: #1a3a1a;
  color: #7ddf7d;
}

.hwp-setup-done {
  text-align: center;
  padding: 16px;
  background: var(--background-secondary);
  border-radius: 8px;
  margin-top: 16px;
}

.hwp-setup-done h2 {
  margin-top: 0;
}

.hwp-setup-footer {
  margin-top: 16px;
  text-align: center;
}

/* ================================================================
   TEMPLATE / PRESET / STYLE MODALS
   ================================================================ */

.hwp-template-picker,
.hwp-preset-picker {
  max-width: 560px;
  padding: 0 8px;
}

.hwp-template-section {
  margin-bottom: 12px;
}

.hwp-template-picker h2,
.hwp-preset-picker h2 {
  margin-bottom: 4px;
}

.hwp-template-picker h3,
.hwp-preset-picker h3 {
  font-size: 14px;
  margin-top: 16px;
  margin-bottom: 8px;
  padding-bottom: 4px;
  border-bottom: 1px solid var(--hwp-toolbar-border);
}

/* 스타일 에디터 — 2칸 레이아웃 */
.hwp-style-editor {
  max-width: 1200px;
  width: 90vw;
  padding: 0 8px;
}

.hwp-style-editor-layout {
  display: flex;
  gap: 24px;
  align-items: flex-start;
}

.hwp-style-editor-controls {
  flex: 1;
  min-width: 0;
  overflow-y: auto;
  max-height: 70vh;
}

.hwp-style-editor-preview {
  width: 360px;
  flex-shrink: 0;
  position: sticky;
  top: 0;
}

.hwp-style-level-section {
  margin-bottom: 20px;
  padding: 12px 16px;
  background: var(--background-secondary);
  border-radius: 8px;
  border-left: 3px solid var(--hwp-primary);
}

.hwp-style-level-section h3 {
  margin-top: 0;
  font-size: 14px;
  margin-bottom: 8px;
}

.hwp-style-preview-box {
  background: var(--hwp-paper-bg);
  border: 1px solid var(--hwp-paper-border);
  border-radius: 6px;
  padding: 20px 24px;
  min-height: 200px;
  color: #1a1a1a;
  box-shadow: var(--hwp-paper-shadow);
}

.hwp-style-preview-line {
  margin: 0;
  padding: 2px 0;
}

/* 좁은 화면에서 1칸으로 */
@media (max-width: 700px) {
  .hwp-style-editor-layout {
    flex-direction: column;
  }

  .hwp-style-editor-preview {
    width: 100%;
    position: relative;
    order: -1;
  }
}

/* ================================================================
   STATUS BAR INDICATOR
   ================================================================ */

.hwp-status-indicator {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
}

.hwp-status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  display: inline-block;
}

.hwp-status-dot.connected {
  background: #28a745;
}

.hwp-status-dot.disconnected {
  background: #dc3545;
}

.docx-preview-container {
  height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--background-secondary);
}

.hanmark-docx-preview-toolbar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--background-modifier-border);
  background: var(--background-primary);
}

.hanmark-docx-preview-label {
  font-weight: 700;
}

.hanmark-docx-preview-status {
  margin-right: auto;
  padding: 2px 8px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 999px;
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
}

.hanmark-docx-preview-status[data-state="actual"],
.hanmark-docx-preview-status[data-state="exact"] {
  border-color: var(--interactive-accent);
  color: var(--text-accent);
}

.hanmark-docx-preview-status[data-state="building"] {
  color: var(--text-normal);
}

.hanmark-docx-preview-status[data-state="stale"] {
  border-color: var(--text-warning);
  color: var(--text-warning);
}

.docx-preview-content {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  overflow: auto;
  padding: 16px;
  --hanmark-docx-preview-zoom: 1;
}

.hanmark-docx-preview-content[data-fit="40"] { --hanmark-docx-preview-zoom: .4; }
.hanmark-docx-preview-content[data-fit="45"] { --hanmark-docx-preview-zoom: .45; }
.hanmark-docx-preview-content[data-fit="50"] { --hanmark-docx-preview-zoom: .5; }
.hanmark-docx-preview-content[data-fit="55"] { --hanmark-docx-preview-zoom: .55; }
.hanmark-docx-preview-content[data-fit="60"] { --hanmark-docx-preview-zoom: .6; }
.hanmark-docx-preview-content[data-fit="65"] { --hanmark-docx-preview-zoom: .65; }
.hanmark-docx-preview-content[data-fit="70"] { --hanmark-docx-preview-zoom: .7; }
.hanmark-docx-preview-content[data-fit="75"] { --hanmark-docx-preview-zoom: .75; }
.hanmark-docx-preview-content[data-fit="80"] { --hanmark-docx-preview-zoom: .8; }
.hanmark-docx-preview-content[data-fit="85"] { --hanmark-docx-preview-zoom: .85; }
.hanmark-docx-preview-content[data-fit="90"] { --hanmark-docx-preview-zoom: .9; }
.hanmark-docx-preview-content[data-fit="95"] { --hanmark-docx-preview-zoom: .95; }
.hanmark-docx-preview-content[data-fit="100"] { --hanmark-docx-preview-zoom: 1; }

.hanmark-docx-preview-content .docx-preview-docx .docx-wrapper,
.hanmark-docx-preview-content .hanmark-docx-preview-paper {
  zoom: var(--hanmark-docx-preview-zoom);
}

.hanmark-docx-preview-content .hanmark-docx-preview-paper {
  transform-origin: top center;
}

.hanmark-docx-preview-content .docx-preview-docx,
.hanmark-docx-preview-content .hanmark-docx-preview-stage {
  min-width: max-content;
}

.docx-preview-loading,
.docx-preview-error,
.docx-preview-warning,
.docx-preview-empty,
.hanmark-docx-preview-loading,
.hanmark-docx-preview-error,
.hanmark-docx-preview-warning,
.hanmark-docx-preview-empty {
  padding: 16px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 10px;
  background: var(--background-primary);
  margin-bottom: 12px;
}

.docx-preview-pdf-frame {
  width: 100%;
  min-height: 80vh;
  border: 0;
}

.word-template-modal-shell {
  width: min(1360px, 94vw);
  max-width: min(1360px, 94vw);
}

.word-template-modal-shell .modal-content {
  width: min(1360px, 94vw);
  max-width: min(1360px, 94vw);
  height: min(88vh, 1050px);
  overflow: hidden;
  padding: 0;
}

.word-template-modal {
  display: flex;
  flex-direction: column;
  gap: 16px;
  height: 100%;
  padding: 16px;
  overflow: hidden;
}

.word-template-header {
  position: sticky;
  top: 0;
  z-index: 5;
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  padding: 12px 14px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 14px;
  background: var(--background-primary);
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.06);
}

.word-template-header-group {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 220px;
  flex: 1 1 260px;
}

.word-template-header-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
}

.word-template-template-select {
  min-width: 180px;
  width: min(320px, 100%);
}

.word-template-dirty-status {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
}

.word-template-dirty-status.is-dirty {
  color: var(--text-accent);
}

.word-template-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  flex: 2 1 520px;
  flex-wrap: wrap;
}

.word-template-actions button {
  min-height: 30px;
  padding: 0 10px;
  white-space: nowrap;
}

.word-template-layout {
  display: grid;
  grid-template-columns: 220px minmax(0, 540px) minmax(360px, 1fr);
  gap: 16px;
  align-items: stretch;
  min-height: 0;
  flex: 1;
  overflow: hidden;
}

.word-template-sidebar,
.word-template-editor,
.word-template-preview {
  border: 1px solid var(--background-modifier-border);
  border-radius: 14px;
  padding: 14px;
  background: var(--background-primary);
  min-height: 0;
  overflow: hidden;
}

.word-template-sidebar {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.word-template-style-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  overflow: auto;
  min-height: 0;
}

.word-template-editor {
  overflow: auto;
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding-right: 8px;
}

.word-template-preview {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.word-style-button {
  width: 100%;
  text-align: left;
  margin: 0;
}

.word-style-button.is-active {
  background: var(--interactive-accent);
  color: var(--text-on-accent);
}

.word-template-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--background-modifier-border-hover);
}

.word-template-section:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}

.word-template-section h4 {
  margin: 0;
}

.word-template-field {
  display: grid;
  grid-template-columns: minmax(90px, 120px) minmax(0, 1fr);
  gap: 10px;
  align-items: start;
}

.word-template-field-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
  padding-top: 8px;
}

.word-template-field-control {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  min-width: 0;
}

.word-template-inline-group {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.word-template-input,
.word-template-select {
  min-height: 32px;
}

.word-template-input {
  width: 100%;
  min-width: 0;
  padding: 6px 10px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 8px;
  background: var(--background-primary);
}

.word-template-input-number {
  width: 96px;
}

.word-template-input-color {
  width: 110px;
}

.word-template-select {
  min-width: 120px;
  max-width: 100%;
}

.word-template-chip {
  min-height: 30px;
  padding: 0 10px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 999px;
  background: var(--background-secondary);
}

.word-template-chip.is-active {
  background: var(--interactive-accent);
  color: var(--text-on-accent);
  border-color: var(--interactive-accent);
}

.word-template-color-group {
  gap: 6px;
}

.word-template-color-picker {
  width: 40px;
  min-width: 40px;
  height: 32px;
  padding: 2px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 8px;
  background: var(--background-primary);
}

.word-font-combobox {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 34px;
  width: 100%;
  min-width: 0;
}

.word-font-combobox-input {
  width: 100%;
  min-width: 0;
  height: 32px;
  padding: 6px 10px;
  border: 1px solid var(--background-modifier-border);
  border-right: 0;
  border-radius: 8px 0 0 8px;
  background: var(--background-primary);
}

.word-font-combobox-toggle {
  height: 32px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 0 8px 8px 0;
  background: var(--background-secondary);
}

.word-font-combobox-panel {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  right: 0;
  z-index: 12;
  display: none;
  flex-direction: column;
  gap: 4px;
  max-height: 280px;
  overflow: auto;
  padding: 8px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 12px;
  background: var(--background-primary);
  box-shadow: 0 14px 28px rgba(0, 0, 0, 0.18);
}

.word-font-combobox.is-open .word-font-combobox-panel {
  display: flex;
}

.word-font-option,
.word-font-option-manual {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 10px;
  border: 1px solid transparent;
  border-radius: 10px;
  cursor: pointer;
}

.word-font-option:hover,
.word-font-option.is-highlighted,
.word-font-option-manual:hover {
  border-color: var(--interactive-accent);
  background: color-mix(in srgb, var(--interactive-accent) 12%, transparent);
}

.word-font-option-name {
  font-size: 13px;
  font-weight: 600;
}

.word-font-option-sample {
  font-size: 14px;
  color: var(--text-muted);
}

.word-font-empty {
  padding: 8px 10px;
  color: var(--text-muted);
  font-size: 12px;
}

.word-font-custom-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 8px;
}

.word-font-custom-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 10px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 10px;
  background: var(--background-secondary);
}

.word-font-custom-row > div {
  min-width: 0;
}

.word-font-custom-row button {
  flex: 0 0 auto;
}

.word-template-preview-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.word-preview-tabs {
  display: flex;
  gap: 8px;
}

.word-preview-tabs .is-active {
  background: var(--interactive-accent);
  color: var(--text-on-accent);
}

.word-template-preview-stage {
  flex: 1;
  min-height: 320px;
  max-height: calc(88vh - 220px);
  overflow: auto;
  padding: 18px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 12px;
  background: linear-gradient(180deg, var(--background-secondary) 0%, var(--background-primary) 100%);
}

.word-template-preview-paper {
  margin: 0 auto;
  background: #fff;
  box-shadow: 0 18px 36px rgba(0, 0, 0, 0.12);
  border-radius: 10px;
  color: #111;
}

@media (max-width: 1320px) {
  .word-template-layout {
    grid-template-columns: 220px minmax(0, 1fr);
  }

  .word-template-preview {
    grid-column: 1 / -1;
  }
}

@media (max-width: 980px) {
  .word-template-modal-shell,
  .word-template-modal-shell .modal-content {
    width: min(96vw, 96vw);
    max-width: min(96vw, 96vw);
  }

  .word-template-layout {
    grid-template-columns: 1fr;
  }

  .word-template-field {
    grid-template-columns: 1fr;
    gap: 6px;
  }

  .word-template-field-label {
    padding-top: 0;
  }
}



/* HWP Writer toolbar skin settings */
.hwp-toolbar-skin-tabs {
  margin: 12px 0 18px;
}

.hwp-toolbar-skin-tab-list {
  display: flex;
  gap: 6px;
  margin-bottom: 10px;
}

.hwp-toolbar-skin-tab {
  border: 1px solid var(--background-modifier-border);
  border-radius: 4px;
  background: var(--background-secondary);
  color: var(--text-normal);
  cursor: pointer;
  padding: 5px 10px;
}

.hwp-toolbar-skin-tab.is-active {
  background: var(--interactive-accent);
  border-color: var(--interactive-accent);
  color: var(--text-on-accent);
}

.hwp-toolbar-skin-tab-panel {
  border-left: 3px solid var(--background-modifier-border);
  padding-left: 12px;
}

.hwp-toolbar-skin-tab-panel h4 {
  margin: 0 0 6px;
}

.hwp-toolbar-skin-hex-input {
  font-family: var(--font-monospace);
  text-transform: uppercase;
  width: 90px;
}

/* HanMark 작업창: Obsidian의 작은 기본 모달 제한을 풀고 데스크톱 작업창처럼 사용한다. */
.modal-container .modal.hanmark-resizable-workspace-modal {
  position: relative;
  width: 94vw;
  height: 90vh;
  min-width: min(760px, calc(100vw - 16px));
  min-height: min(560px, calc(100vh - 16px));
  max-width: calc(100vw - 16px);
  max-height: calc(100vh - 16px);
  resize: both;
  overflow: hidden;
}

/* PDF 테마 작업창은 노트북에서도 처음부터 거의 전체 화면으로 열고,
   제목줄을 제외한 실제 내용만 스크롤되도록 한다. */
.modal-container
  .modal.hanmark-resizable-workspace-modal.hanmark-pdf-theme-workspace-modal {
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  width: 96vw;
  height: 94vh;
}

.modal-container
  .modal.hanmark-resizable-workspace-modal.hanmark-pdf-theme-workspace-modal
  > .modal-title {
  flex: 0 0 auto;
}

.modal-container
  .modal.hanmark-resizable-workspace-modal.hanmark-pdf-theme-workspace-modal
  > .modal-content {
  flex: 1 1 auto;
  width: 100%;
  height: auto;
  min-width: 0;
  min-height: 0;
  max-width: none;
  max-height: none;
  overflow: auto;
  overscroll-behavior: contain;
}

.modal-container .modal.hanmark-resizable-workspace-modal::after {
  content: "";
  position: absolute;
  right: 3px;
  bottom: 3px;
  width: 14px;
  height: 14px;
  border-right: 2px solid var(--text-faint);
  border-bottom: 2px solid var(--text-faint);
  pointer-events: none;
}

.modal-container .modal.hanmark-resizable-workspace-modal > .modal-content,
.modal-container .modal.hanmark-resizable-workspace-modal .modal-content.hanmark-export-modal,
.modal-container .modal.hanmark-resizable-workspace-modal .modal-content.hanmark-template-manager,
.modal-container .modal.hanmark-resizable-workspace-modal .modal-content.hanmark-document-style-modal {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  max-width: none;
  max-height: none;
  overflow: auto;
  resize: none;
}

.hanmark-window-size-hint {
  display: block;
  margin: -4px 0 10px;
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
}

@media (max-width: 800px), (max-height: 650px) {
  .modal-container .modal.hanmark-resizable-workspace-modal {
    width: calc(100vw - 8px);
    height: calc(100vh - 8px);
    min-width: 0;
    min-height: 0;
    max-width: calc(100vw - 8px);
    max-height: calc(100vh - 8px);
  }
}

@media (max-width: 1440px), (max-height: 900px) {
  .modal-container
    .modal.hanmark-resizable-workspace-modal.hanmark-pdf-theme-workspace-modal {
    width: calc(100vw - 8px);
    height: calc(100vh - 8px);
  }
}

/* Editorial PDF theme builder */
.hanmark-export-pdf-theme {
  margin-top: 14px;
  padding-top: 14px;
  border-top: 1px solid var(--background-modifier-border);
}

.hanmark-export-pdf-theme-status,
.hanmark-pdf-theme-manager-status {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 3px 9px;
  align-items: center;
  margin-top: 10px;
  padding: 10px 12px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 10px;
  background: var(--background-secondary);
}

.hanmark-export-pdf-theme-status > span:last-child,
.hanmark-pdf-theme-manager-status > span:last-child {
  grid-column: 2;
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
}

.hanmark-export-pdf-theme-status.has-warning,
.hanmark-pdf-theme-manager-status.has-warning {
  border-color: var(--color-orange);
}

.hanmark-export-pdf-theme-swatch,
.hanmark-pdf-theme-swatch {
  width: 24px;
  height: 24px;
  border: 1px solid var(--background-modifier-border-hover);
  border-radius: 50%;
  background: var(
    --hanmark-pdf-theme-swatch-color,
    var(--hanmark-pdf-preview-key, #002e6e)
  );
  box-shadow: inset 0 0 0 2px color-mix(in srgb, white 60%, transparent);
}

.hanmark-export-pdf-theme-status .hanmark-export-pdf-theme-swatch,
.hanmark-pdf-theme-manager-status .hanmark-pdf-theme-swatch {
  grid-row: 1 / 3;
}

.hanmark-pdf-theme-manager,
.hanmark-pdf-theme-builder {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
}

.modal-container
  .modal.hanmark-pdf-theme-workspace-modal
  > .modal-content.hanmark-pdf-theme-builder {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.hanmark-pdf-theme-builder-intro {
  flex: 0 0 auto;
}

.hanmark-pdf-theme-manager > p,
.hanmark-pdf-theme-builder-intro > p,
.hanmark-pdf-theme-builder-panel > p {
  color: var(--text-muted);
  line-height: 1.5;
}

.hanmark-pdf-theme-list {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin: 16px 0;
}

.hanmark-pdf-theme-row {
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  min-height: 52px;
  padding: 9px 12px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 10px;
  background: var(--background-secondary);
  cursor: pointer;
}

.hanmark-pdf-theme-row:hover {
  background: var(--background-modifier-hover);
}

.hanmark-pdf-theme-row:focus-within {
  outline: 3px solid var(--interactive-accent);
  outline-offset: 2px;
}

.hanmark-pdf-theme-row.is-selected {
  border-color: var(--interactive-accent);
  background: color-mix(
    in srgb,
    var(--interactive-accent) 10%,
    var(--background-secondary)
  );
}

.hanmark-pdf-theme-row-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.hanmark-pdf-theme-row-copy small {
  overflow: hidden;
  color: var(--text-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.hanmark-pdf-theme-actions,
.hanmark-pdf-theme-library-actions,
.hanmark-pdf-theme-builder-footer {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 14px;
}

.hanmark-pdf-theme-library-actions {
  padding-top: 14px;
  border-top: 1px solid var(--background-modifier-border);
}

.hanmark-pdf-theme-steps {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin: 12px 0 16px;
}

.hanmark-pdf-theme-steps button {
  min-height: 42px;
  white-space: normal;
}

.hanmark-pdf-theme-steps button[aria-current="step"] {
  border-color: var(--interactive-accent);
  background: var(--interactive-accent);
  color: var(--text-on-accent);
}

.hanmark-pdf-theme-builder-panel {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  overscroll-behavior: contain;
  padding: 16px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 14px;
  background: var(--background-primary-alt);
}

.hanmark-pdf-theme-builder-panel h3 {
  margin-top: 0;
}

.hanmark-pdf-theme-field-label {
  color: var(--text-normal);
  font-size: var(--font-ui-small);
  font-weight: var(--font-semibold);
}

.hanmark-pdf-theme-color-field {
  display: grid;
  grid-template-columns: minmax(120px, auto) 56px minmax(150px, 1fr);
  gap: 8px;
  align-items: center;
  margin: 12px 0;
}

.hanmark-pdf-theme-color-field input[type="color"],
.hanmark-pdf-theme-override-controls input[type="color"] {
  width: 50px;
  min-width: 50px;
  height: 36px;
  padding: 2px;
  cursor: pointer;
}

.hanmark-pdf-theme-color-field small {
  grid-column: 2 / -1;
  color: var(--text-muted);
}

.hanmark-pdf-theme-text-columns {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.hanmark-pdf-theme-text-columns h4 {
  margin: 4px 0 10px;
}

.hanmark-pdf-theme-text-field {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-bottom: 10px;
}

.hanmark-pdf-theme-text-field input,
.hanmark-pdf-theme-text-field select,
.hanmark-pdf-theme-color-field input[type="text"] {
  width: 100%;
}

.hanmark-pdf-theme-text-field small {
  color: var(--text-muted);
}

.hanmark-pdf-theme-toggle {
  display: flex;
  gap: 8px;
  align-items: center;
  margin: 10px 0;
  cursor: pointer;
}

.hanmark-pdf-theme-diagnostics {
  margin: 12px 0;
  padding: 11px 13px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 10px;
  background: var(--background-secondary);
}

.hanmark-pdf-theme-diagnostics.is-safe {
  border-color: var(--color-green);
}

.hanmark-pdf-theme-diagnostics.has-warning {
  border-color: var(--color-orange);
}

.hanmark-pdf-theme-diagnostics ul {
  margin: 7px 0 0;
  padding-left: 20px;
  color: var(--text-muted);
}

.hanmark-pdf-theme-diagnostics p {
  margin: 8px 0 0;
  color: var(--text-normal);
}

.hanmark-pdf-theme-preview {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin: 14px 0;
}

.hanmark-pdf-theme-preview-cover,
.hanmark-pdf-theme-preview-page {
  position: relative;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  aspect-ratio: 210 / 297;
  border: 1px solid var(--hanmark-pdf-preview-border);
  border-radius: 6px;
  background: white;
  color: var(--hanmark-pdf-preview-body);
  box-shadow: var(--shadow-s);
}

.hanmark-pdf-theme-preview-cover-top {
  display: flex;
  flex: 0 0 52%;
  flex-direction: column;
  align-items: center;
  min-height: 52%;
  padding: 8%;
  --bold-color: var(--hanmark-pdf-preview-on-key);
  background: var(--hanmark-pdf-preview-key);
  color: var(--hanmark-pdf-preview-on-key);
  font-size: 0.66em;
  font-weight: 700;
  text-align: center;
}

.hanmark-pdf-theme-preview-cover-kicker,
.hanmark-pdf-theme-preview-cover-edition,
.hanmark-pdf-theme-preview-cover-title,
.hanmark-pdf-theme-preview-cover-subtitle {
  color: inherit;
}

.hanmark-pdf-theme-preview-cover-kicker,
.hanmark-pdf-theme-preview-cover-edition,
.hanmark-pdf-theme-preview-cover-subtitle {
  min-height: 1em;
}

.hanmark-pdf-theme-preview-cover-edition {
  margin-top: 7%;
  letter-spacing: 0.12em;
}

.hanmark-pdf-theme-preview-cover-title {
  margin: auto 0 0;
  font-size: 1.35em;
  line-height: 1.25;
}

.hanmark-pdf-theme-preview-cover-subtitle {
  margin: 7% 0 auto;
  font-size: 0.82em;
  font-weight: 500;
}

.hanmark-pdf-theme-preview-cover-body {
  display: flex;
  flex: 1;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 8%;
  --bold-color: var(--hanmark-pdf-preview-key-ink);
  color: var(--hanmark-pdf-preview-key-ink);
  text-align: center;
}

.hanmark-pdf-theme-preview-cover-brand,
.hanmark-pdf-theme-preview-cover-system {
  color: inherit;
}

.hanmark-pdf-theme-preview-cover-brand {
  min-height: 1.5em;
  font-size: 1.05em;
}

.hanmark-pdf-theme-preview-cover-system {
  min-height: 1em;
  font-size: 0.78em;
}

.hanmark-pdf-theme-preview-cover-detail {
  min-height: 1em;
  color: var(--hanmark-pdf-preview-muted-ink);
  font-size: 0.7em;
}

.hanmark-pdf-theme-preview-tags {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 4px;
  min-height: 24px;
  margin-top: 12px;
}

.hanmark-pdf-theme-preview-tags span {
  padding: 3px 7px;
  border-radius: 999px;
  background: var(--hanmark-pdf-preview-key);
  color: var(--hanmark-pdf-preview-on-key);
  font-size: 0.58em;
}

.hanmark-pdf-theme-preview-header,
.hanmark-pdf-theme-preview-footer {
  display: flex;
  justify-content: space-between;
  min-height: 1.2em;
  margin: 7% 8% 0;
  padding-bottom: 5px;
  border-bottom: 2px solid var(--hanmark-pdf-preview-accent);
  color: var(--hanmark-pdf-preview-key-ink);
  font-size: 0.58em;
  font-weight: 700;
}

.hanmark-pdf-theme-preview-body {
  flex: 1;
  padding: 8%;
  font-size: 0.7em;
}

.hanmark-pdf-theme-preview-body h3 {
  color: var(--hanmark-pdf-preview-key-ink);
}

.hanmark-pdf-theme-preview-body pre {
  margin-top: 12px;
  padding: 8px;
  overflow: hidden;
  background: var(--hanmark-pdf-preview-key);
  color: var(--hanmark-pdf-preview-on-key);
  white-space: pre-wrap;
}

.hanmark-pdf-theme-preview-body pre code {
  padding: 0;
  background: transparent;
  color: inherit;
}

.hanmark-pdf-theme-preview-footer {
  margin-top: 0;
  margin-bottom: 7%;
  padding-top: 5px;
  padding-bottom: 0;
  border-top: 2px solid var(--hanmark-pdf-preview-accent);
  border-bottom: 0;
}

.hanmark-pdf-theme-advanced {
  margin-top: 12px;
  padding: 10px 12px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 10px;
  background: var(--background-secondary);
}

.hanmark-pdf-theme-advanced > summary {
  cursor: pointer;
  font-weight: var(--font-semibold);
}

.hanmark-pdf-theme-advanced > p {
  color: var(--text-muted);
  line-height: 1.5;
}

.hanmark-pdf-theme-override {
  display: grid;
  grid-template-columns: minmax(160px, 1fr) auto;
  gap: 3px 12px;
  align-items: center;
  padding: 10px 0;
  border-top: 1px solid var(--background-modifier-border);
}

.hanmark-pdf-theme-override > small {
  color: var(--text-muted);
}

.hanmark-pdf-theme-override > button,
.hanmark-pdf-theme-override-controls {
  grid-column: 2;
  grid-row: 1 / 3;
}

.hanmark-pdf-theme-override-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
}

.hanmark-pdf-theme-override-controls input[type="text"] {
  width: 104px;
}

.hanmark-pdf-theme-override-ratio {
  grid-column: 1 / -1;
  color: var(--text-muted);
  font-size: var(--font-ui-smaller);
}

.hanmark-pdf-theme-override-ratio.has-warning,
input[aria-invalid="true"] + .hanmark-pdf-theme-override-ratio {
  color: var(--color-orange);
}

.hanmark-pdf-theme-builder-footer {
  position: static;
  flex: 0 0 auto;
  z-index: 2;
  padding: 12px 0 2px;
  border-top: 1px solid var(--background-modifier-border);
  background: var(--background-primary);
}

.hanmark-pdf-theme-builder button:focus-visible,
.hanmark-pdf-theme-manager button:focus-visible,
.hanmark-pdf-theme-builder input:focus-visible,
.hanmark-pdf-theme-manager input:focus-visible,
.hanmark-pdf-theme-builder select:focus-visible,
.hanmark-export-pdf-theme button:focus-visible,
.hanmark-export-pdf-theme select:focus-visible {
  outline: 3px solid var(--interactive-accent);
  outline-offset: 2px;
}

@media (max-width: 900px) {
  .hanmark-pdf-theme-text-columns,
  .hanmark-pdf-theme-preview {
    grid-template-columns: 1fr;
  }

  .hanmark-pdf-theme-color-field {
    grid-template-columns: 50px minmax(0, 1fr);
  }

  .hanmark-pdf-theme-color-field > label,
  .hanmark-pdf-theme-color-field small {
    grid-column: 1 / -1;
  }

  .hanmark-pdf-theme-row {
    grid-template-columns: auto auto minmax(0, 1fr);
  }

  .hanmark-pdf-theme-row .hanmark-template-active {
    grid-column: 3;
  }

  .hanmark-pdf-theme-override {
    grid-template-columns: 1fr;
  }

  .hanmark-pdf-theme-override > button,
  .hanmark-pdf-theme-override-controls {
    grid-column: 1;
    grid-row: auto;
  }
}
